import numpy as np
from scipy import stats
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 4

def design(feats):
    # Identify strong univariate predictors
    strong_uni = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] != 'derived':
            t_stat, p_val = stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i])
            if abs(t_stat) > 10 and p_val < 1e-10:
                strong_uni.append((fid, abs(t_stat)))

    # Sort by strength
    strong_uni.sort(key=lambda x: x[1], reverse=True)

    # Check for product terms among top features
    top_features = [fid for fid, _ in strong_uni[:10]]

    # Find correlated pairs with |r| >= 0.6
    correlations = {}
    for i, fid1 in enumerate(top_features):
        for j, fid2 in enumerate(top_features[i+1:], i+1):
            col1 = feats.column(fid1)
            col2 = feats.column(fid2)
            corr = np.corrcoef(feats.x[:, col1], feats.x[:, col2])[0, 1]
            if abs(corr) >= 0.6:
                correlations[(fid1, fid2)] = corr

    # Look for strongest product term
    best_product = None
    best_t = 0

    for (f1, f2), corr in correlations.items():
        col1 = feats.column(f1)
        col2 = feats.column(f2)
        product = feats.x[:, col1] * feats.x[:, col2]

        # Test significance of product term
        t_stat, p_val = stats.ttest_ind(product[feats.y==1], product[feats.y==0])
        if abs(t_stat) > best_t and p_val < 1e-5:
            best_t = abs(t_stat)
            best_product = (f1, f2)

    if best_product:
        return Design(
            drivers=(best_product[0], best_product[1]),
            columns=(best_product[0], best_product[1]),
            products=(best_product,),
            loadings={}
        )

    # No strong product term found, return strongest single features
    if strong_uni:
        drivers = tuple([fid for fid, _ in strong_uni[:MAX_DRIVERS]])
        return Design(
            drivers=drivers,
            columns=drivers,
            products=(),
            loadings={}
        )

    # No mechanism
    return Design(
        drivers=(),
        columns=(),
        products=(),
        loadings={}
    )

